// Educational IPv4 next-hop/listener model, not a packet emulator or real network tool.
export const builderKey='devops-custom-network-v1';
export const deviceTypes=['client','router','firewall','load-balancer','app','database','dns'];
export function ipNumber(ip){const p=String(ip).split('.');if(p.length!==4||p.some(s=>!/^(0|[1-9]\d{0,2})$/.test(s)||Number(s)>255))throw Error('Use an IPv4 address such as 10.0.1.10.');return p.reduce((n,s)=>n*256+Number(s),0);}
export function cidrInfo(value){const [ip,prefix,...rest]=String(value).trim().split('/');if(rest.length||!/^\d{1,2}$/.test(prefix)||Number(prefix)<8||Number(prefix)>30)throw Error('Use IPv4 CIDR with a prefix from /8 to /30.');const n=ipNumber(ip),bits=Number(prefix),block=2**(32-bits),base=Math.floor(n/block)*block;return {ip,n,bits,base,end:base+block-1};}
export function inCidr(ip,cidr){const c=cidrInfo(cidr),n=ipNumber(ip);return n>=c.base&&n<=c.end;}
export function parseInterfaces(text){return String(text).split(/[\s,]+/).filter(Boolean).map(v=>v.trim());}
export function parseRules(text){if(!text.trim())return [];return text.trim().split('\n').map(line=>{const [protocol,port,source,...extra]=line.trim().split(/\s+/);if(extra.length||!['TCP','UDP'].includes(protocol)||!(port==='any'||/^\d+$/.test(port))||port!=='any'&&(Number(port)<1||Number(port)>65535))throw Error('Rule format: TCP 8080 10.0.1.0/24 (or use any for the destination port).');cidrInfo(source);return {protocol,port:port==='any'?null:Number(port),source};});}
export function parseRoutes(text){if(!text.trim())return [];return text.trim().split('\n').map(line=>{const [cidr,via,gateway,...extra]=line.trim().split(/\s+/);if(extra.length||via!=='via')throw Error('Route format: 10.0.3.0/24 via 10.0.2.2');cidrInfo(cidr);ipNumber(gateway);return {cidr,gateway};});}
export function validateNetwork(input){if(!input||input.version!==1||!Array.isArray(input.nodes)||!Array.isArray(input.links)||input.nodes.length>24||input.links.length>48)throw Error('Use a version 1 design with at most 24 devices and 48 links.');const ids=new Set(),ips=new Set();const nodes=input.nodes.map(n=>{if(!n||!/^n\d{1,5}$/.test(n.id)||ids.has(n.id))throw Error('Device IDs must be unique n1, n2, etc.');ids.add(n.id);if(!deviceTypes.includes(n.type)||typeof n.name!=='string'||!n.name.trim()||n.name.length>60)throw Error('Each device needs a supported type and a name up to 60 characters.');if(!Array.isArray(n.interfaces)||n.interfaces.length<1||n.interfaces.length>4)throw Error('Each device needs 1–4 interface addresses.');for(const address of n.interfaces){const c=cidrInfo(address);if(c.n===c.base||c.n===c.end)throw Error('Use a host address, not the network or broadcast address.');if(ips.has(c.n))throw Error('Two interfaces cannot use the same IPv4 address.');ips.add(c.n);}if(n.gateway)ipNumber(n.gateway);if(!['TCP','UDP'].includes(n.protocol)||!Number.isInteger(n.port)||n.port<1||n.port>65535)throw Error('Choose TCP/UDP and a listener port from 1 to 65535.');if(!Number.isFinite(n.x)||!Number.isFinite(n.z)||Math.abs(n.x)>40||Math.abs(n.z)>40)throw Error('Place devices between -40 and 40 on X and Z.');const routes=Array.isArray(n.routes)?n.routes:[],rules=Array.isArray(n.rules)?n.rules:[];if(routes.length>12||rules.length>12)throw Error('Use at most 12 routes and 12 firewall allow rules per device.');for(const r of routes){cidrInfo(r.cidr);ipNumber(r.gateway);}for(const r of rules){cidrInfo(r.source);if(!['TCP','UDP'].includes(r.protocol)||r.port!==null&&(!Number.isInteger(r.port)||r.port<1||r.port>65535))throw Error('Invalid firewall allow rule.');}if(n.type==='load-balancer'&&n.protocol!=='TCP')throw Error('This proxy model supports TCP only; use a separate DNS endpoint for UDP examples.');if(n.type==='load-balancer'&&(!Number.isInteger(n.backendPort)||n.backendPort<1||n.backendPort>65535))throw Error('Choose a backend port from 1 to 65535.');return {id:n.id,name:n.name.trim(),type:n.type,interfaces:[...n.interfaces],gateway:n.gateway||'',protocol:n.protocol,port:n.port,x:n.x,z:n.z,routes:routes.map(r=>({...r})),rules:rules.map(r=>({...r})),stateful:n.stateful!==false,backend:n.backend||'',backendPort:n.backendPort||8080};});for(const n of nodes)if(n.backend&&(!ids.has(n.backend)||n.backend===n.id||['router','firewall'].includes(nodes.find(p=>p.id===n.backend)?.type)))throw Error('A load balancer backend must reference another existing device.');const seen=new Set();const links=input.links.map(l=>{if(!l||!ids.has(l.from)||!ids.has(l.to)||l.from===l.to)throw Error('Connect two different existing devices.');const key=[l.from,l.to].sort().join(':');if(seen.has(key))throw Error('That link already exists.');seen.add(key);return {from:l.from,to:l.to};});return {version:1,nodes,links};}
export function blankNetwork(){return {version:1,nodes:[],links:[]};}
export function newDevice(id,type='app',index=0){return {id,type,name:type+' '+id,interfaces:['10.0.2.'+(20+index)+'/24'],gateway:'10.0.2.1',protocol:type==='dns'?'UDP':'TCP',port:type==='dns'?53:type==='database'?5432:8080,x:-12+(index%4)*8,z:Math.floor(index/4)*8,routes:[],rules:[],stateful:true,backend:'',backendPort:8080};}
export function exampleNetwork(proxy=false){const client={...newDevice('n1','client'),name:'Browser / client',interfaces:['10.0.1.10/24'],gateway:'10.0.1.1',x:-12,z:0};const firewall={...newDevice('n2','firewall'),name:'Gateway + firewall',interfaces:['10.0.1.1/24','10.0.2.1/24'],gateway:'',rules:[{protocol:'TCP',port:proxy?443:8080,source:'10.0.1.0/24'}],x:0,z:0};const app={...newDevice('n3','app'),name:'Application',interfaces:['10.0.2.10/24'],x:12,z:0};const nodes=[client,firewall,app],links=[{from:'n1',to:'n2'},{from:'n2',to:'n3'}];if(proxy){nodes.push({...newDevice('n4','load-balancer'),name:'TLS edge (transport model)',interfaces:['10.0.2.20/24'],port:443,backend:'n3',backendPort:8080,x:7,z:-8});links[1]={from:'n2',to:'n4'};links.push({from:'n4',to:'n3'});}return validateNetwork({version:1,nodes,links});}
export function parseDesign(raw){if(typeof raw!=='string'||raw.length>65536)throw Error('Import JSON up to 64 KiB.');return validateNetwork(JSON.parse(raw));}
export function removeDevice(net,id){return validateNetwork({...net,nodes:net.nodes.filter(n=>n.id!==id).map(n=>({...n,backend:n.backend===id?'':n.backend})),links:net.links.filter(l=>l.from!==id&&l.to!==id)});}
function iface(n,ip){return n.interfaces.find(c=>inCidr(ip,c));}
function allowed(n,protocol,port,source){return n.rules.some(r=>r.protocol===protocol&&(r.port===null||r.port===port)&&inCidr(source,r.source));}
function nextHop(net,current,target,ip){const connected=iface(current,ip);let hop;if(connected)hop=ip;else{const route=current.routes.filter(r=>inCidr(ip,r.cidr)).sort((a,b)=>cidrInfo(b.cidr).bits-cidrInfo(a.cidr).bits)[0];hop=route?.gateway||current.gateway;if(!hop)return {error:'No connected route, matching static route or default gateway for '+ip+'.'};if(!iface(current,hop))return {error:'Next hop '+hop+' is outside every local interface subnet.'};}const neighbors=net.links.filter(l=>l.from===current.id||l.to===current.id).map(l=>net.nodes.find(n=>n.id===(l.from===current.id?l.to:l.from)));const next=neighbors.find(n=>n.interfaces.some(c=>cidrInfo(c).ip===hop)&&n.interfaces.some(c=>current.interfaces.some(a=>inCidr(cidrInfo(c).ip,a)&&inCidr(cidrInfo(a).ip,c))));if(!next)return {error:'No drawn link to next hop '+hop+' on a mutually reachable subnet.'};if(next.id!==target.id&&!['router','firewall'].includes(next.type))return {error:next.name+' is an endpoint, not a transit router.'};return {next};}
export function traceNetwork(input,{from,to,port,protocol='TCP'}){const net=validateNetwork(input),source=net.nodes.find(n=>n.id===from),destination=net.nodes.find(n=>n.id===to),steps=[];if(!source||!destination||from===to)throw Error('Choose different source and destination devices.');if(['router','firewall'].includes(source.type)||['router','firewall'].includes(destination.type))throw Error('Choose endpoint devices for the request. Routers and firewalls forward/filter; this model does not give them application listeners.');if(!Number.isInteger(port)||port<1||port>65535||!['TCP','UDP'].includes(protocol))throw Error('Choose a valid destination port and TCP/UDP.');const block=(node,text)=>{steps.push({from:node.id,to:node.id,phase:'blocked',title:'Stopped at '+node.name,text,packet:'No successful response is implied.',blocked:true});return {ok:false,steps,summary:text};};let origin=source,target=destination,listenerPort=port;const segments=[],visitedTargets=new Set();
 while(true){if(visitedTargets.has(target.id))return block(origin,'Load balancer backend cycle detected.');visitedTargets.add(target.id);const serverIP=cidrInfo(target.interfaces[0]).ip;const first=nextHop(net,origin,target,serverIP);if(first.error)return block(origin,first.error);const local=origin.interfaces.find(c=>first.next.interfaces.some(i=>inCidr(cidrInfo(i).ip,c)))||origin.interfaces[0];const sourceIP=cidrInfo(local).ip,path=[origin];let current=origin;const seen=new Set([current.id]);const clientPort=49152+segments.length;
  while(current.id!==target.id){if(current.type==='firewall'&&!allowed(current,protocol,listenerPort,sourceIP))return block(current,'Default-deny firewall has no matching allow rule for '+protocol+' destination :'+listenerPort+' from '+sourceIP+'.');const hop=nextHop(net,current,target,serverIP);if(hop.error)return block(current,hop.error);if(seen.has(hop.next.id))return block(current,'Forwarding loop detected. Review gateways and static routes.');seen.add(hop.next.id);steps.push({from:current.id,to:hop.next.id,phase:'request',title:'Forward toward '+target.name,text:current.type==='router'||current.type==='firewall'?'Routing/filtering does not create a new application connection.':'The endpoint initiates this modeled transport exchange.',packet:`${protocol} ${sourceIP}:${clientPort} → ${serverIP}:${listenerPort}`,serverPort:listenerPort,initiator:origin.id});current=hop.next;path.push(current);if(path.length>24)return block(current,'Path exceeds the model limit.');}
  if(target.protocol!==protocol||target.port!==listenerPort)return block(target,'Listener mismatch: request uses '+protocol+' :'+listenerPort+', but this endpoint declares '+target.protocol+' :'+target.port+'.');segments.push({path,sourceIP,serverIP,clientPort,serverPort:listenerPort,origin:origin.id});if(target.type!=='load-balancer')break;if(!target.backend)return block(target,'The load balancer listener was reached, but no backend is configured.');steps.push({from:target.id,to:target.id,phase:'proxy',title:'Start a separate backend connection',text:'The proxy terminates the front transport exchange and initiates a different backend exchange. TLS/certificates and application health are not simulated.',packet:`New ${protocol} connection → backend :${target.backendPort}`});origin=target;target=net.nodes.find(n=>n.id===target.backend);listenerPort=origin.backendPort;}
 for(const segment of [...segments].reverse()){const path=[...segment.path].reverse();for(let i=0;i<path.length-1;i++){const current=path[i],next=path[i+1];if(current.type==='firewall'&&!current.stateful&&!allowed(current,protocol,segment.clientPort,segment.serverIP))return block(current,'Stateless return denied: allow '+protocol+' destination client port :'+segment.clientPort+' from '+segment.serverIP+' or deliberately enable established-return handling.');const check=nextHop(net,current,path.at(-1),segment.sourceIP);if(check.error)return block(current,'Return route failed: '+check.error);if(check.next.id!==next.id)return block(current,'Return routing differs from the modeled reverse path; asymmetric routing is outside this exercise.');steps.push({from:current.id,to:next.id,phase:'response',title:'Return on the modeled exchange',text:current.type==='firewall'&&current.stateful?'This firewall allows return traffic for the exchange accepted above.':'Return routing is checked separately; the server port is the response source port.',packet:`${protocol} ${segment.serverIP}:${segment.serverPort} → ${segment.sourceIP}:${segment.clientPort}`,serverPort:segment.serverPort,initiator:segment.origin});}}
 return {ok:true,steps,summary:(destination.type==='dns'?'DNS transport example completed. DNS does not forward a subsequent HTTP request. ':'')+'Modeled route, firewall, listener and reverse-path checks passed. This is not proof of TCP/TLS, authentication, DNS records, application health or a real network.'};}
